## Code Example
```javascript
function verifySignature(payload, sig, secret) {
  const h = require('crypto').createHmac('sha256', secret);
  h.update(payload, 'utf8');
  const digest = h.digest('hex');
  return require('crypto').timingSafeEqual(Buffer.from(digest), Buffer.from(sig));
}
```

